177	+// A provider reads back from its cache only the unchanged opening of a
178	+// request, and the host's replay of a finished turn is a shorter retelling
179	+// (no thinking, no pictures, no workspace beside the person's words) that
180	+// matches nothing it cached. So the chat's finished turns open the next turn
181	+// as they were sent, when the history the host sends for it is exactly what
182	+// it sent for the last turn followed by its replay of that turn. Anything
183	+// else, such as another chat, a history trimmed or restored, or a note
184	+// between turns, is sent as the host replays it.
185	+void ProviderAgent::carry_finished_turns(const AgentRequest& request)
186	+{
187	+    m_carried_replay.clear();
188	+    if (!m_finished || request.conversation_id.empty() || m_finished->conversation_id != request.conversation_id ||
189	+        m_finished->instructions != m_transcript.instructions || !same_tools(m_finished->tools, m_transcript.tools))
190	+        return;
191	+    const FinishedTurns&                         finished = *m_finished;
192	+    const std::vector<AgentConversationContext>& history  = request.conversation;
193	+    const std::size_t                            kept     = finished.opening.size() + finished.replay.size();
194	+    if (history.size() < kept || !std::equal(finished.opening.begin(), finished.opening.end(), history.begin(), same_entry) ||
195	+        !std::equal(finished.replay.begin(), finished.replay.end(), history.begin() + finished.opening.size(), same_entry))
196	+        return;
197	+    // The rest is the replay of the last turn: its user message, if the host
198	+    // replays one, then its words and the calls the host ran, in order.
199	+    std::vector<std::string> calls;
200	+    for (auto entry = history.begin() + kept; entry != history.end(); ++entry) {
201	+        if (!entry->call_id.empty())
202	+            calls.push_back(entry->call_id);
203	+        else if (entry->role != "assistant" && !(entry->role == "user" && entry == history.begin() + kept))
204	+            return;
205	+    }
206	+    // Carried turns are sent whole, never trimmed. Past this size the turn
207	+    // goes out as the host replays it, trimmed to the host's budget, and
208	+    // carrying starts over from there.
209	+    constexpr std::size_t kCarriedBytes = 128 * 1024;
210	+    if (calls != finished.last_calls || carried_bytes(finished.turns) > kCarriedBytes)
211	+        return;
212	+    m_carried_replay.assign(history.begin() + finished.opening.size(), history.end());
213	+    m_transcript.opening = finished.opening;
214	+    m_transcript.carried = finished.turns;
215	+}
