403	+// An Anthropic service that answers each reply request with the next
404	+// scripted stream, at once, and keeps every body it was sent. A title
405	+// request is answered with a title and takes nothing from the script.
406	+class ScriptedAnthropicTransport final : public IAgentHttpTransport
407	+{
408	+public:
409	+    bool post(AgentHttpRequest request, EventFn event) override
410	+    {
411	+        json body = json::parse(request.body);
412	+        const bool title = !body.contains("tools");
413	+        std::string stream = response("A strong part");
414	+        if (!title) {
415	+            REQUIRE(!streams.empty());
416	+            stream = std::move(streams.front());
417	+            streams.pop_front();
418	+            replies.push_back(std::move(body));
